import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a number system of base {base}, let the forbidden digit set be [forbidden_digits]. Determine the least positive integer n such that for every way of expressing {base}^n as the product of {m} positive integers, at least one factor, when written in base {base}, contains a digit from the forbidden set [forbidden_digits].'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generalize the seed by allowing multiple factors and a forbidden digit set.
# To keep instances solvable yet nontrivial, we use base 10 with m in {2,3} and
# a forbidden set that always includes 0 (and sometimes another digit).
base = 10
m = rng.choice([2, 3])
# Always include 0. With probability, add one extra forbidden digit to increase difficulty.
candidates = list(range(1, base))
rng.shuffle(candidates)
if m == 2:
    # For m=2, sometimes add an extra digit to make it stricter and thus change thresholds.
    extra_ct = rng.choice([0, 1])
else:
    # For m=3, keep only {0} to avoid triviality (too strong forbidden set leads to tiny n).
    extra_ct = 0
extras = candidates[:extra_ct]
forbidden_digits = [0] + extras
return {'base': base, 'm': m, 'forbidden_digits': forbidden_digits}

    def verifier(assign):
# Validate input domain and compute the minimal n.
# Returns (True, answer) if valid; else (False, None).
try:
    base = assign.get('base', None)
    m = assign.get('m', None)
    forbidden = assign.get('forbidden_digits', None)
    # Basic validation
    if not isinstance(base, int) or base < 3:
        # base at least 3 for meaningful positional digits
        return (False, None)  # invalid base
    if not isinstance(m, int) or m < 2 or m > 3:
        return (False, None)  # only m in {2,3} supported for difficulty and runtime control
    if not isinstance(forbidden, list) or len(forbidden) == 0:
        return (False, None)
    if any((not isinstance(d, int)) for d in forbidden):
        return (False, None)
    if any(d < 0 or d >= base for d in forbidden):
        return (False, None)
    # Enforce difficulty: forbid at least digit 0
    if 0 not in forbidden:
        return (False, None)
    # Avoid triviality: do not forbid all digits in base
    if len(set(forbidden)) >= base:
        return (False, None)
    # For this family we keep base = 10 to ensure robust behavior and known properties.
    if base != 10:
        return (False, None)

    # Helpers
    def factorize(n):
        # prime factorization of n with exponents
        x = n
        fac = []
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                fac.append((p, e))
            p += 1 if p == 2 else 2  # minor speed-up: after 2, test odd numbers
        if x > 1:
            fac.append((x, 1))
        return fac

    def to_base_digits(val, b):
        # returns list of digits in base b (least significant first)
        if val == 0:
            return [0]
        digs = []
        v = val
        while v > 0:
            digs.append(v % b)
            v //= b
        return digs

    def avoids_forbidden(val, b, forb_set):
        digs = to_base_digits(val, b)
        fs = forb_set
        for d in digs:
            if d in fs:
                return False
        return True

    # Base factorization
    fac = factorize(base)
    # Require at least two distinct primes for structural richness (base 10 -> OK)
    if len(fac) < 2:
        return (False, None)

    primes = [p for (p, e) in fac]
    exps_in_base = [e for (p, e) in fac]
    dim = len(primes)
    forb_set = set(forbidden)

    # Enumerate zero-forbidden divisors of base^n via exponent vectors t in [0..e_i*n]
    def enumerate_vectors(n):
        # returns set of exponent vectors (as tuples) whose numeric value avoids forbidden digits
        E = [e * n for e in exps_in_base]
        # recursion over dim
        vectors = []
        def rec(idx, cur_exp, cur_val):
            if idx == dim:
                # cur_val = product primes[i]^cur_exp[i]
                if avoids_forbidden(cur_val, base, forb_set):
                    vectors.append(tuple(cur_exp))
                return
            p = primes[idx]
            for t in range(E[idx] + 1):
                # multiply value by p^t
                # small optimization: exponentiation once per branch
                rec(idx + 1, cur_exp + [t], cur_val * (p ** t))
        rec(0, [], 1)
        return set(vectors), [e * n for e in exps_in_base]

    # Check existence of an m-tuple of vectors summing to E
    def exists_m_tuple(n):
        vecs_set, E = enumerate_vectors(n)
        if m == 2:
            # Check for any t with E - t also in vecs_set
            if not vecs_set:
                return False
            # Precompute complements lookup
            # Represent vectors as tuples; compute complement as tuple of E[i] - t[i]
            vecs = vecs_set
            # Using set membership for O(1) complements check
            for t in vecs:
                comp = tuple(E[i] - t[i] for i in range(dim))
                if comp in vecs:
                    return True
            return False
        else:
            # m == 3: check existence of t1 + t2 + t3 = E
            vecs = list(vecs_set)
            if len(vecs) == 0:
                return False
            # Build set for quick membership
            vecs_lookup = vecs_set
            # Early pruning: if any coordinate of E is 0, then all three must sum to 0 on that coordinate
            # which forces t's to have 0 in that coordinate. This doesn't eliminate but can hint trivial case.
            # Meet-in-the-middle: enumerate pair sums t1+t2 and test if E - (t1+t2) in vecs
            # Stop early when found.
            from itertools import product
            # If vecs size is large, this can be heavy; but forbidden set includes 0 which drastically reduces vecs.
            V = vecs
            L = len(V)
            # Small optimization: if len(V) is huge, cap attempt to avoid explosion
            # But we must be correct: we do full search. We keep manageable by generator choices.
            for i in range(L):
                t1 = V[i]
                for j in range(L):
                    t2 = V[j]
                    s = tuple(t1[k] + t2[k] for k in range(dim))
                    # s must be componentwise <= E
                    ok = True
                    for k in range(dim):
                        if s[k] > E[k]:
                            ok = False
                            break
                    if not ok:
                        continue
                    comp = tuple(E[k] - s[k] for k in range(dim))
                    if comp in vecs_lookup:
                        return True
            return False

    # We seek the least n such that NO m-tuple exists (i.e., every m-factorization forces a forbidden digit).
    # Incrementally search n.
    # We set a reasonable cap to prevent non-termination in pathological cases.
    max_n = 100
    answer = None
    for n in range(1, max_n + 1):
        has_tuple = exists_m_tuple(n)
        if not has_tuple:
            answer = n
            break
    if answer is None:
        return (False, None)  # Didn't find within search cap; instance too hard or invalid
    return (True, answer)
except Exception:
    # In case of unexpected errors, mark invalid
    return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

